GAD.reg("pyq","o-p6-rtp-nov2019",[{"id":"o-p6-rtp-nov2019-m1","section":"I","no":1,"marks":null,"type":"MCQ","stem":"Judging the significance of a matter requires _____of the facts and circumstances.","options":["objective analysis","subjective analysis","Both subjective and objective analysis","qualitative analysis"],"answer":{"kind":"single","value":"A"},"key_raw":"A","label":"MCQ 1","ord":0,"ans":"**(A)**","ours":{"difficulty":"easy"},"pg":{"q":"2","a":"9"},"tags":["aud.doc.sa230"]},{"id":"o-p6-rtp-nov2019-m2","section":"I","no":2,"marks":null,"type":"MCQ","stem":"An important factor in determining the form, content and extent of audit documentation of significant matters is the extent of _________exercised in performing the work and evaluating the results.","options":["professional skepticism","professional integrity","professional judgment","Professional sincerity"],"answer":{"kind":"single","value":"C"},"key_raw":"C","label":"MCQ 2","ord":1,"ans":"**(C)**","ours":{"difficulty":"easy"},"pg":{"q":"2","a":"9"},"tags":["aud.doc.sa230"]},{"id":"o-p6-rtp-nov2019-m3","section":"I","no":3,"marks":null,"type":"MCQ","stem":"Audit evidence is necessary to support the auditor’s opinion and report. It is_____in nature and is primarily obtained from audit procedures performed during the course of the audit.","options":["cumulative","regressive","selective","objective"],"answer":{"kind":"single","value":"A"},"key_raw":"A","label":"MCQ 3","ord":2,"ans":"**(A)**","ours":{"difficulty":"easy"},"pg":{"q":"2","a":"9"},"tags":["aud.evid.sa500"]},{"id":"o-p6-rtp-nov2019-m4","section":"I","no":4,"marks":null,"type":"MCQ","stem":"______refer to the audit procedures performed to obtain an understanding of the entity and its environment, including the entity’s internal control, to identify and assess the risks of material misstatement, whether due to fraud or error, at the financial statement and assertion levels.","options":["Audit assessment procedures","substantive procedures","test of control","Risk assessment procedures"],"answer":{"kind":"single","value":"D"},"key_raw":"D","label":"MCQ 4","ord":3,"ans":"**(D)**","ours":{"difficulty":"easy"},"pg":{"q":"3","a":"9"},"tags":["aud.risk.sa315"]},{"id":"o-p6-rtp-nov2019-m5","section":"I","no":5,"marks":null,"type":"MCQ","stem":"When more persuasive audit evidence is needed regarding the effectiveness of a control,","options":["it may be appropriate to increase the extent of testing of the control and reduce the extent of the degree of reliance on controls.","it may be appropriate to decrease the extent of testing of the control as well as the degree of reliance on controls.","it may be appropriate to decrease the extent of testing of the control and increase the extent of the degree of reliance on controls.","it may be appropriate to increase the extent of testing of the control as well as the degree of reliance on controls."],"answer":{"kind":"single","value":"D"},"key_raw":"D","label":"MCQ 5","ord":4,"ans":"**(D)**","ours":{"approach":"More persuasive evidence about a control goes with relying on it more: ask what that does to the extent of testing.","difficulty":"medium"},"pg":{"q":"3","a":"9"},"tags":["aud.risk.sa330","aud.risk.testing"]},{"id":"o-p6-rtp-nov2019-m6","section":"I","no":6,"marks":null,"type":"MCQ","stem":"When deviations from controls upon which the auditor intends to rely are detected,","options":["the auditor shall not make any inquiries to understand these matters and their potential consequences","the auditor shall make specific inquiries to understand these matters and their potential consequences","the auditor shall make general inquiries to understand these matters and their potential consequences","the auditor shall make both general as well as specific inquiries to understand these matters and their potential consequences"],"answer":{"kind":"single","value":"B"},"key_raw":"B","label":"MCQ 6","ord":5,"ans":"**(B)**","ours":{"difficulty":"easy"},"pg":{"q":"3","a":"9"},"tags":["aud.risk.sa330","aud.risk.testing"]},{"id":"o-p6-rtp-nov2019-m7","section":"I","no":7,"marks":null,"type":"MCQ","stem":"Which of the following statement is correct :","options":["Substantive analytical procedures are generally more applicable to large volumes of transactions that tend to be predictable over time","Substantive analytical procedures are generally less applicable to large volumes of transactions that tend to be predictable over time","Substantive analytical procedures are generally more applicable to small volumes of transactions that tend to be predictable over time","None of the above"],"answer":{"kind":"single","value":"A"},"key_raw":"A","label":"MCQ 7","ord":6,"ans":"**(A)**","ours":{"difficulty":"easy"},"pg":{"q":"3","a":"9"},"tags":["aud.evid.sa520"]},{"id":"o-p6-rtp-nov2019-m8","section":"I","no":8,"marks":null,"type":"MCQ","stem":"If the auditor is unable to obtain sufficient appropriate audit evidence regarding the opening balances, the auditor shall express:","options":["a disclaimer opinion","a qualified opinion","a qualified opinion or a disclaimer of opinion, as appropriate, in accordance with SA 705.","unmodified opinion"],"answer":{"kind":"single","value":"C"},"key_raw":"C","label":"MCQ 8","ord":7,"ans":"**(C)**","ours":{"difficulty":"easy"},"pg":{"q":"4","a":"9"},"tags":["aud.evid.sa510","aud.report.sa705"]},{"id":"o-p6-rtp-nov2019-m9","section":"I","no":9,"marks":null,"type":"MCQ","stem":"A failure of the confirming party to respond, or fully respond, to a positive confirmation request, or a confirmation request returned undelivered is called-","options":["Negative confirmation request","Non-response","Exception","Positive confirmation request"],"answer":{"kind":"single","value":"B"},"key_raw":"B","label":"MCQ 9","ord":8,"ans":"**(B)**","ours":{"difficulty":"easy"},"pg":{"q":"4","a":"9"},"tags":["aud.evid.sa505"]},{"id":"o-p6-rtp-nov2019-m10","section":"I","no":10,"marks":null,"type":"MCQ","stem":"In case of a company that is required to constitute an Audit Committee under section 177, the committee, and, in cases where such a committee is not required to be constituted, __________, shall take into consideration the qualifications and experience of the individual or the firm proposed to be considered for appointment as auditor and whether such qualifications and experience are commensurate with the size and requirements of the company.","options":["the board","any director","Managing Director","Whole time director"],"answer":{"kind":"single","value":"A"},"key_raw":"A","label":"MCQ 10","ord":9,"ans":"**(A)**","ours":{"difficulty":"easy"},"pg":{"q":"4","a":"9"},"oos":true,"note":"Out of syllabus (old scheme, ours): who considers the qualifications and experience of a proposed auditor before the appointment (the Audit Committee under section 177 or, where none is required, the Board; Rule 3 of the Companies (Audit and Auditors) Rules, 2014) belonged to old Paper 6's Chapter 10, The Company Audit; the new-scheme Paper 5 syllabus and the January 2027 Study Material do not cover the appointment of a company auditor, so the item carries only the nearest chapter (as o-p6-pyq-jan2021 and o-p6-rtp-nov2022 q23).","tags":["aud.ethics"]},{"id":"o-p6-rtp-nov2019-q1i","section":"II","no":1,"marks":null,"type":"DESC","stem":"As per Section 139(6), the first auditor of a company, including a Government company, shall be appointed by the Board of Directors within 60 days from the date of registration of the company.","group":{"kind":"case","id":"o-p6-rtp-nov2019-c1","label":null,"context":"State with reason (in short) whether the following statements are true or false:"},"label":"Q1(i)","part":"(i)","ord":10,"ans":"**Incorrect:** As per **Section 139(6),** the first auditor of a company, other than a Government company, shall be appointed by the Board of Directors within 30 days from the date of registration of the company.","ours":{"difficulty":"easy"},"pg":{"q":"4","a":"9"},"oos":true,"note":"Out of syllabus (old scheme, ours): the appointment of a company's first auditor under section 139(6) of the Companies Act, 2013 belonged to old Paper 6's Chapter 10, The Company Audit; the new-scheme Paper 5 syllabus and the January 2027 Study Material do not cover the appointment of a company auditor, so the item carries only the nearest chapter (as m10).","case":"o-p6-rtp-nov2019-c1","tags":["aud.ethics"]},{"id":"o-p6-rtp-nov2019-q1ii","section":"II","no":1,"marks":null,"type":"DESC","stem":"As per section 140(2) of the Act, the auditor who has resigned from the company need not inform the Registrar of Companies.","group":{"kind":"case","id":"o-p6-rtp-nov2019-c1","label":null,"context":"State with reason (in short) whether the following statements are true or false:"},"label":"Q1(ii)","part":"(ii)","ord":11,"ans":"**Incorrect:** As per section 140(2) of the Act, the auditor who has resigned from the company shall file within a period of 30 days from the date of resignation, a statement in the prescribed Form ADT–3 (as per Rule 8 of CAAR) with the company and the Registrar.","ours":{"difficulty":"easy"},"pg":{"q":"4","a":"9"},"oos":true,"note":"Out of syllabus (old scheme, ours): the resigning auditor's statement in Form ADT-3 under section 140(2) of the Companies Act, 2013 belonged to old Paper 6's Chapter 10, The Company Audit (appointment, removal and resignation of auditors); the new-scheme Paper 5 syllabus and the January 2027 Study Material do not teach it, so the item carries only the nearest chapter (as m10).","case":"o-p6-rtp-nov2019-c1","tags":["aud.ethics"]},{"id":"o-p6-rtp-nov2019-q1iii","section":"II","no":1,"marks":null,"type":"DESC","stem":"Preconditions for an audit have not been defined in SA 210 “Agreeing the Terms of Audit Engagements.”","group":{"kind":"case","id":"o-p6-rtp-nov2019-c1","label":null,"context":"State with reason (in short) whether the following statements are true or false:"},"label":"Q1(iii)","part":"(iii)","ord":12,"ans":"**Incorrect:** As per SA 210 “Agreeing the Terms of Audit Engagements”, preconditions for an audit may be defined as the use by management of an acceptable financial reporting framework in the preparation of the financial statements and the agreement of management and, where appropriate, those charged with governance to the premise on which an audit is conducted.","ours":{"difficulty":"easy"},"pg":{"q":"4","a":"9"},"case":"o-p6-rtp-nov2019-c1","tags":["aud.ethics.sa210"]},{"id":"o-p6-rtp-nov2019-q1iv","section":"II","no":1,"marks":null,"type":"DESC","stem":"The auditor need not discuss elements of planning with the entity’s management in any case.","group":{"kind":"case","id":"o-p6-rtp-nov2019-c1","label":null,"context":"State with reason (in short) whether the following statements are true or false:"},"label":"Q1(iv)","part":"(iv)","ord":13,"ans":"**Incorrect:** The auditor may decide to discuss elements of planning with the entity’s management to facilitate the conduct and management of the audit engagement.","ours":{"difficulty":"easy"},"pg":{"q":"4","a":"9"},"case":"o-p6-rtp-nov2019-c1","tags":["aud.plan.sa300"]},{"id":"o-p6-rtp-nov2019-q1v","section":"II","no":1,"marks":null,"type":"DESC","stem":"Planning is a discrete phase of an audit.","group":{"kind":"case","id":"o-p6-rtp-nov2019-c1","label":null,"context":"State with reason (in short) whether the following statements are true or false:"},"label":"Q1(v)","part":"(v)","ord":14,"ans":"**Incorrect:** According to SA-300, “Planning an Audit of Financial Statements”, planning is not a discrete phase of an audit, but rather a continual and iterative process that often begins shortly after (or in connection with) the completion of the previous audit and continues until the completion of the current audit engagement. The auditor shall establish an overall audit strategy that sets the scope, timing and direction of the audit, and that guides the development of the audit plan.","ours":{"difficulty":"easy"},"pg":{"q":"5","a":"9","cq":"4"},"case":"o-p6-rtp-nov2019-c1","tags":["aud.plan.sa300"]},{"id":"o-p6-rtp-nov2019-q1vi","section":"II","no":1,"marks":null,"type":"DESC","stem":"Subjective examination connotes critical examination and scrutiny of the accounting statements.","group":{"kind":"case","id":"o-p6-rtp-nov2019-c1","label":null,"context":"State with reason (in short) whether the following statements are true or false:"},"label":"Q1(vi)","part":"(vi)","ord":15,"ans":"**Incorrect:** Objective examination connotes critical examination and scrutiny of the accounting statements of the undertaking with a view to assessing how far the statements present the actual state of affairs in the correct context and whether they give a true and fair view about the financial results and state of affairs.","ours":{"difficulty":"easy"},"pg":{"q":"5","a":"10","cq":"4"},"case":"o-p6-rtp-nov2019-c1","tags":["aud.nature.basics","aud.evid.sa500"]},{"id":"o-p6-rtp-nov2019-q1vii","section":"II","no":1,"marks":null,"type":"DESC","stem":"Inquiry alone provides sufficient audit evidence of the absence of a material misstatement at the assertion level and of the operating effectiveness of controls.","group":{"kind":"case","id":"o-p6-rtp-nov2019-c1","label":null,"context":"State with reason (in short) whether the following statements are true or false:"},"label":"Q1(vii)","part":"(vii)","ord":16,"ans":"**Incorrect:** Although inquiry may provide important audit evidence, and may even produce evidence of a misstatement, inquiry alone ordinarily does not provide sufficient audit evidence of the absence of a material misstatement at the assertion level, nor of the operating effectiveness of controls.","ours":{"difficulty":"easy"},"pg":{"q":"5","a":"10","cq":"4"},"case":"o-p6-rtp-nov2019-c1","tags":["aud.evid.sa500"]},{"id":"o-p6-rtp-nov2019-q1viii","section":"II","no":1,"marks":null,"type":"DESC","stem":"The assessment of risks is a matter capable of precise measurement.","group":{"kind":"case","id":"o-p6-rtp-nov2019-c1","label":null,"context":"State with reason (in short) whether the following statements are true or false:"},"label":"Q1(viii)","part":"(viii)","ord":17,"ans":"**Incorrect:** The assessment of risks is based on audit procedures to obtain information necessary for that purpose and evidence obtained throughout the audit. The assessment of risks is a matter of professional judgment, rather than a matter capable of precise measurement.","ours":{"difficulty":"easy"},"pg":{"q":"5","a":"10","cq":"4"},"case":"o-p6-rtp-nov2019-c1","tags":["aud.risk.model","aud.risk.sa315"]},{"id":"o-p6-rtp-nov2019-q1ix","section":"II","no":1,"marks":null,"type":"DESC","stem":"According to Section 53 of the Companies Act, 2013, a company can issue shares at a discount.","group":{"kind":"case","id":"o-p6-rtp-nov2019-c1","label":null,"context":"State with reason (in short) whether the following statements are true or false:"},"label":"Q1(ix)","part":"(ix)","ord":18,"ans":"**Incorrect:** According to Section 53 of the Companies Act, 2013, a company shall not issue shares at a discount, except in the case of an issue of sweat equity shares given under Section 54 of the Companies Act, 2013.","ours":{"difficulty":"easy"},"pg":{"q":"5","a":"10","cq":"4"},"case":"o-p6-rtp-nov2019-c1","tags":["aud.items.equity"]},{"id":"o-p6-rtp-nov2019-q1x","section":"II","no":1,"marks":null,"type":"DESC","stem":"An intangible asset is an identifiable monetary asset.","group":{"kind":"case","id":"o-p6-rtp-nov2019-c1","label":null,"context":"State with reason (in short) whether the following statements are true or false:"},"label":"Q1(x)","part":"(x)","ord":19,"ans":"**Incorrect:** An intangible asset is an identifiable non-monetary asset, without physical substance, held for use in the production or supply of goods or services, for rental to others, or for administrative purposes.","ours":{"difficulty":"easy"},"pg":{"q":"5","a":"10","cq":"4"},"case":"o-p6-rtp-nov2019-c1","tags":["aud.items.ppe"]},{"id":"o-p6-rtp-nov2019-q2a","section":"II","no":2,"marks":null,"type":"DESC","stem":"An auditor who, before the completion of the engagement, is requested to change the engagement to one which provides a lower level of assurance, should consider the appropriateness of doing so. Explain stating the factors based on which client can request the auditor to change the engagement.","label":"Q2(a)","part":"(a)","ord":20,"ans":"An auditor who, before the completion of the engagement, is requested to change the engagement to one which provides a lower level of assurance, should consider the appropriateness of doing so.\n\nA request from the client for the auditor to change the engagement may result from -\n\n1. a **change in circumstances** affecting the need for the service,\n2. **a misunderstanding** as to the nature of an audit or related service originally requested.\n3. **a restriction on the scope of the engagement**, whether imposed by management or caused by circumstances.","ours":{"difficulty":"easy"},"pg":{"q":"5","a":"10"},"tags":["aud.ethics.sa210"]},{"id":"o-p6-rtp-nov2019-q2b","section":"II","no":2,"marks":null,"type":"DESC","stem":"The firm should **establish policies and procedures** designed to provide it with reasonable assurance that the policies and procedures relating to the system of quality control are relevant, adequate, operating effectively and complied with in practice. Such policies and procedures should include an ongoing consideration and evaluation of the firm’s system of quality control, including a periodic inspection of a selection of completed engagements. Explain in the above context the purpose of monitoring compliance with quality control policies and procedures.","label":"Q2(b)","part":"(b)","ord":21,"ans":"The firm should **establish policies and procedures** designed to provide it with reasonable assurance that the policies and procedures relating to the system of quality control are relevant, adequate, operating effectively and complied with in practice. Such policies and procedures should include an ongoing consideration and evaluation of the firm’s system of quality control, including a periodic inspection of a selection of completed engagements.\n\nThe purpose of monitoring compliance with quality control policies and procedures is to provide an evaluation of:\n\n(a) Adherence to professional standards and regulatory and legal requirements;\n\n(b) Whether the quality control system has been appropriately designed and effectively implemented; and\n\n(c) Whether the firm’s quality control policies and procedures have been appropriately applied, so that reports that are issued by the firm or engagement partners are appropriate in the circumstances.\n\nFollow-up by appropriate firm personnel so that necessary modifications are promptly made to the quality control policies and procedures.","ours":{"difficulty":"easy"},"pg":{"q":"5","a":"10-11"},"tags":["aud.ethics.qc"]},{"id":"o-p6-rtp-nov2019-q3a","section":"II","no":3,"marks":null,"type":"DESC","stem":"The Chartered Accountant has a responsibility to remain independent by taking into account the context in which they practice, the threats to independence and the safeguards available to eliminate the threats.\n\nIn the above context, explain the guiding principles.","label":"Q3(a)","part":"(a)","ord":22,"ans":"The Chartered Accountant has a responsibility to remain independent by taking into account the context in which they practice, the threats to independence and the safeguards available to eliminate the threats.\n\nThe following are the guiding principles in this regard: -\n\n1. For the public to have confidence in the quality of audit, it is essential that auditors should always be and appears to be independent of the entities that they are auditing.\n2. In the case of audit, the key fundamental principles are integrity, objectivity and professional skepticism, which necessarily require the auditor to be independent.\n3. Before taking on any work, an auditor must conscientiously consider whether it involves threats to his independence.\n4. When such threats exist, the auditor should either desist from the task or put in place safeguards that eliminate them.\n5. If the auditor is unable to fully implement credible and adequate safeguards, then he must not accept the work.","ours":{"difficulty":"easy"},"pg":{"q":"5","a":"11"},"tags":["aud.ethics.independence"]},{"id":"o-p6-rtp-nov2019-q3b","section":"II","no":3,"marks":null,"type":"DESC","stem":"Write a note on “Self-review threats”","label":"Q3(b)","part":"(b)","ord":23,"ans":"**Self-review threats**, which occur when during a review of any judgement or conclusion reached in a previous audit or non-audit engagement (Non audit services include any professional services provided to an entity by an auditor, other than audit or review of the financial statements. These include management services, internal audit, investment advisory service, design and implementation of information technology systems etc.), or when a member of the audit team was previously a director or senior employee of the client. Instances where such threats come into play are (i) when an auditor having recently been a director or senior officer of the company, and (ii) when auditors perform services that are themselves subject matters of audit.","ours":{"difficulty":"easy"},"pg":{"q":"5","a":"11"},"tags":["aud.ethics.independence"]},{"id":"o-p6-rtp-nov2019-q4a","section":"II","no":4,"marks":null,"type":"DESC","stem":"Plans should be made to cover acquiring knowledge of the client’s accounting systems, policies and internal control procedures. Explain.","label":"Q4(a)","part":"(a)","ord":24,"ans":"**The auditor should plan his work to enable him to conduct an effective audit** in an efficient and timely manner. Plans should be based on knowledge of the client’s business.\n\n**Plans should be made to cover, among other things:**\n\n(a) acquiring knowledge of the client’s accounting systems, policies and internal control procedures;\n\n(b) establishing the expected degree of reliance to be placed on internal control;\n\n(c) determining and programming the nature, timing, and extent of the audit procedures to be performed; and\n\n(d) coordinating the work to be performed.\n\nFrom the above, it is clear that statement given in the question is partly correct.","ours":{"difficulty":"easy"},"pg":{"q":"5","a":"11-12"},"tags":["aud.plan.sa300"]},{"id":"o-p6-rtp-nov2019-q4b","section":"II","no":4,"marks":null,"type":"DESC","stem":"As a result of unexpected events, changes in conditions, or the audit evidence obtained from the results of audit procedures, the auditor may need to modify the overall audit strategy and audit plan. Explain.","label":"Q4(b)","part":"(b)","ord":25,"ans":"**The auditor shall update and change the overall audit strategy** and the audit plan as necessary during the course of the audit. As a result of unexpected events, changes in conditions, or the audit evidence obtained from the results of audit procedures, the auditor may need to modify the overall audit strategy and audit plan and thereby the resulting planned nature, timing and extent of further audit procedures, based on the revised consideration of assessed risks. This may be the case when information comes to the auditor’s attention that differs significantly from the information available when the auditor planned the audit procedures. **For example,** audit evidence obtained through the performance of substantive procedures may contradict the audit evidence obtained through tests of controls.","ours":{"difficulty":"easy"},"pg":{"q":"5","a":"12"},"tags":["aud.plan.sa300"]},{"id":"o-p6-rtp-nov2019-q5a","section":"II","no":5,"marks":null,"type":"DESC","stem":"Engagement partner of Audit Firm MKC AND COMPANY thinks that Planning an audit would involve establishing the overall audit strategy for the engagement and developing an audit plan. Also, Adequate planning would benefit the audit of financial statements in several ways. Analyse explaining the benefits of adequate planning.","label":"Q5(a)","part":"(a)","ord":26,"ans":"Planning an audit involves establishing the overall audit strategy for the engagement and developing an audit plan. Adequate planning benefits the audit of financial statements in several ways, including the following:\n\n1. Helping the auditor to devote appropriate attention to important areas of the audit.\n2. Helping the auditor identify and resolve potential problems on a timely basis.\n3. Helping the auditor properly organize and manage the audit engagement so that it is performed in an effective and efficient manner.\n4. Assisting in the selection of engagement team members with appropriate levels of capabilities and competence to respond to anticipated risks, and the proper assignment of work to them.\n5. Facilitating the direction and supervision of engagement team members and the review of their work.\n6. Assisting, where applicable, in coordination of work done by auditors of components and experts.","ours":{"difficulty":"easy"},"pg":{"q":"5","a":"12"},"tags":["aud.plan.sa300"]},{"id":"o-p6-rtp-nov2019-q5b","section":"II","no":5,"marks":null,"type":"DESC","stem":"Planning is not a discrete phase of an audit, but rather a continual and iterative process that often begins shortly after the completion of the previous audit and continues until the completion of the current audit engagement. Analyse and Explain.","label":"Q5(b)","part":"(b)","ord":27,"ans":"Planning is not a discrete phase of an audit, but rather a continual and iterative process that often begins shortly after (or in connection with) the completion of the previous audit and continues until the completion of the current audit engagement. Planning, however, includes consideration of the timing of certain activities and audit procedures that need to be completed prior to the performance of further audit procedures. For example, planning includes the need to consider, prior to the auditor’s identification and assessment of the risks of material misstatement, such matters as:\n\n1. The analytical procedures to be applied as risk assessment procedures.\n2. Obtaining a general understanding of the legal and regulatory framework applicable to the entity and how the entity is complying with that framework.\n3. The determination of materiality.\n4. The involvement of experts.\n5. The performance of other risk assessment procedures.","ours":{"difficulty":"easy"},"pg":{"q":"6","a":"12-13"},"tags":["aud.plan.sa300"]},{"id":"o-p6-rtp-nov2019-q6a","section":"II","no":6,"marks":null,"type":"DESC","stem":"Auditing is a logical process. An auditor is called upon to assess the actualities of the situation, review the statements of account and give an expert opinion about the truth and fairness of such accounts. This he cannot do unless he has examined the financial statements objectively. He needs evidence to obtain information for arriving at his judgment. Discuss explaining clearly the detailed meaning of audit evidence.","label":"Q6(a)","part":"(a)","ord":28,"ans":"Auditing is a logical process. An auditor is called upon to assess the actualities of the situation, review the statements of account and give an expert opinion about the truth and fairness of such accounts. This he cannot do unless he has examined the financial statements objectively.\n\nObjective examination connotes critical examination and scrutiny of the accounting statements of the undertaking with a view to assessing how far the statements present the actual state of affairs in the correct context and whether they give a true and fair view about the financial results and state of affairs. An opinion founded on a rather reckless and negligent examination and evaluation may expose the auditor to legal action with consequential loss of professional standing and prestige.\n\nHe needs evidence to obtain information for arriving at his judgment.\n\nAudit evidence may be defined as the information used by the auditor in arriving at the conclusions on which the auditor’s opinion is based. Audit evidence includes both information contained in the accounting records underlying the financial statements and other information.\n\n**Explaining this further, audit evidence includes:-**\n\n(1) **Information contained in the accounting records:** Accounting records include the records of initial accounting entries and supporting records, such as checks and records of electronic fund transfers; invoices; contracts; the general and subsidiary ledgers, journal entries and other adjustments to the financial statements that are not reflected in journal entries; and records such as work sheets and spreadsheets supporting cost allocations, computations, reconciliations and disclosures.\n\n(2) **Other information that authenticates the accounting records and also supports the auditor’s rationale behind the true and fair presentation of the financial statements:** Other information which the auditor may use as audit evidence includes, for example minutes of the meetings, written confirmations from trade receivables and trade payables, manuals containing details of internal control etc. A combination of tests of accounting records and other information is generally used by the auditor to support his opinion on the financial statements.","ours":{"difficulty":"medium"},"pg":{"q":"6","a":"13"},"tags":["aud.evid.sa500"]},{"id":"o-p6-rtp-nov2019-q6b","section":"II","no":6,"marks":null,"type":"DESC","stem":"Audit evidence is necessary to support the auditor’s opinion and report. It is cumulative in nature and is primarily obtained from audit procedures performed during the course of the audit. Most of the auditor’s work in forming the auditor’s opinion consists of obtaining and evaluating audit evidence. Explain","label":"Q6(b)","part":"(b)","ord":29,"ans":"**Audit evidence is necessary to support the auditor’s opinion and report.** It is cumulative in nature and is primarily obtained from audit procedures performed during the course of the audit. It may, however, also include information obtained from other sources such as previous audits. In addition to other sources inside and outside the entity, the entity’s accounting records are an important source of audit evidence. Also, information that may be used as audit evidence may have been prepared using the work of a management’s expert. Audit evidence comprises both information that supports and corroborates management’s assertions, and any information that contradicts such assertions. In addition, in some cases the absence of information (for example, management’s refusal to provide a requested representation) is used by the auditor, and therefore, also constitutes audit evidence.\n\nMost of the auditor’s work in forming the auditor’s opinion consists of obtaining and evaluating audit evidence. Audit procedures to obtain audit evidence can include inspection, observation, confirmation, recalculation, re-performance and analytical procedures, often in some combination, in addition to inquiry. Although inquiry may provide important audit evidence, and may even produce evidence of a misstatement, inquiry alone ordinarily does not provide sufficient audit evidence of the absence of a material misstatement at the assertion level, nor of the operating effectiveness of controls.\n\nAs explained in SA 200, “Overall Objectives of the Independent Auditor and the Conduct of an Audit in Accordance with Standards on Auditing”, reasonable assurance is obtained when the auditor has obtained sufficient appropriate audit evidence to reduce audit risk (i.e., the risk that the auditor expresses an inappropriate opinion when the financial statements are materially misstated) to an acceptably low level. The sufficiency and appropriateness of audit evidence are interrelated.","ours":{"difficulty":"medium"},"pg":{"q":"6","a":"14"},"tags":["aud.evid.sa500"]},{"id":"o-p6-rtp-nov2019-q7a","section":"II","no":7,"marks":null,"type":"DESC","stem":"SQC 1 requires firms to establish policies and procedures for the timely completion of the assembly of audit files. Explain","label":"Q7(a)","part":"(a)","ord":30,"ans":"**The auditor shall assemble the audit documentation in an audit file** and complete the administrative process of assembling the final audit file on a timely basis after the date of the auditor’s report.\n\nSQC 1 “Quality Control for Firms that perform Audits and Review of Historical Financial Information, and other Assurance and related services”, requires firms to establish policies and procedures for the timely completion of the assembly of audit files. An appropriate time limit within which to complete the assembly of the final audit file is ordinarily not more than 60 days after the date of the auditor’s report.\n\nThe completion of the assembly of the final audit file after the date of the auditor’s report is an administrative process that does not involve the performance of new audit procedures or the drawing of new conclusions. Changes may, however, be made to the audit documentation during the final assembly process, if they are administrative in nature.\n\nExamples of such changes include:\n\n- Deleting or discarding superseded documentation.\n- Sorting, collating and cross referencing working papers.\n- Signing off on completion checklists relating to the file assembly process.\n- Documenting audit evidence that the auditor has obtained, discussed and agreed with the relevant members of the engagement team before the date of the auditor’s report.\n\nAfter the assembly of the final audit file has been completed, the auditor shall not delete or discard audit documentation of any nature before the end of its retention period.\n\nSQC 1 requires firms to establish policies and procedures for the retention of engagement documentation. The retention period for audit engagements ordinarily is no shorter than seven years from the date of the auditor’s report, or, if later, the date of the group auditor’s report.","ours":{"difficulty":"easy"},"pg":{"q":"6","a":"14-15"},"tags":["aud.doc.sa230","aud.ethics.qc"]},{"id":"o-p6-rtp-nov2019-q7b","section":"II","no":7,"marks":null,"type":"DESC","stem":"When the use of the going concern basis of accounting is appropriate, assets and liabilities are recorded on the basis that the entity will be able to realize its assets and discharge its liabilities in the normal course of business. Explain stating also the objective of the auditor regarding going concern.","label":"Q7(b)","part":"(b)","ord":31,"ans":"Under the going concern basis of accounting, the financial statements are prepared on the assumption that the entity is a going concern and will continue its operations for the foreseeable future. When the use of the going concern basis of accounting is appropriate, assets and liabilities are recorded on the basis that the entity will be able to realize its assets and discharge its liabilities in the normal course of business.\n\nObjectives of the auditor regarding going concern\n\nThe objectives of the auditor are:\n\n(a) To obtain written representations from management and, where appropriate, those charged with governance that they believe that they have fulfilled their responsibility for the preparation of the financial statements and for the completeness of the information provided to the auditor;\n\n(b) To support other audit evidence relevant to the financial statements or specific assertions in the financial statements by means of written representations, if determined necessary by the auditor or required by other SAs; and\n\n(c) To respond appropriately to written representations provided by management and, where appropriate, those charged with governance, or if management or, where appropriate, those charged with governance do not provide the written representations requested by the auditor.","ours":{"difficulty":"easy"},"pg":{"q":"6","a":"15"},"note":"ICAI's answer gives, under its heading \"Objectives of the auditor regarding going concern\", the three objectives of the auditor regarding written representations (SA 580), as Q8(b)'s answer does; transcribed as printed. The tags name both.","tags":["aud.complete.sa570","aud.complete.sa580"]},{"id":"o-p6-rtp-nov2019-q8a","section":"II","no":8,"marks":null,"type":"DESC","stem":"Discuss the meaning and nature of Audit Documentation.","label":"Q8(a)","part":"(a)","ord":32,"ans":"**Audit documentation:** SA 230 on “Audit Documentation”, audit documentation refers to the record of audit procedures performed, relevant audit evidence obtained, and conclusions the auditor reached. (terms such as “working papers” or “work papers” are also sometimes used.)\n\n**Nature of Audit Documentation**\n\n**Audit documentation provides:**\n\n(a) evidence of the auditor’s basis for a conclusion about the achievement of the overall objectives of the auditor; and\n\n(b) evidence that the audit was planned and performed in accordance with SAs and applicable legal and regulatory requirements.","ours":{"difficulty":"easy"},"pg":{"q":"6","a":"15-16"},"tags":["aud.doc.sa230"]},{"id":"o-p6-rtp-nov2019-q8b","section":"II","no":8,"marks":null,"type":"DESC","stem":"Explain clearly objective of the auditor regarding written representation.","label":"Q8(b)","part":"(b)","ord":33,"ans":"**The objectives of the auditor regarding written representation**\n\nThe objectives of the auditor are:\n\n(a) **To obtain written representations**\n\nTo obtain written representations from management. Also that management believes that it has fulfilled its responsibility for the preparation of the financial statements and for the completeness of the information provided to the auditor;\n\n(b) **To support other evidence**\n\nTo support other audit evidence relevant to the financial statements or specific assertions in the financial statements by means of written representations; and\n\n(c) **To respond appropriately**\n\nTo respond appropriately to written representations provided by management or if management does not provide the written representations requested by the auditor.","ours":{"difficulty":"easy"},"pg":{"q":"6","a":"16"},"tags":["aud.complete.sa580"]},{"id":"o-p6-rtp-nov2019-q9a","section":"II","no":9,"marks":null,"type":"DESC","stem":"Based on the results of the tests of control, the auditor should evaluate whether the internal controls are designed and operating as contemplated in the preliminary assessment of control risk. Analyse and Explain.","label":"Q9(a)","part":"(a)","ord":34,"ans":"**While obtaining audit evidence about the effective operation of internal controls,** the auditor considers how they were applied, the consistency with which they were applied during the period and by whom they were applied. The concept of effective operation recognises that some deviations may have occurred. Deviations from prescribed controls may be caused by such factors as changes in key personnel, significant seasonal fluctuations in volume of transactions and human error. When deviations are detected the auditor makes specific inquiries regarding these matters, particularly, the timing of staff changes in key internal control functions. The auditor then ensures that the tests of control appropriately cover such a period of change or fluctuation.\n\nBased on the results of the tests of control, the auditor should evaluate whether the internal controls are designed and operating as contemplated in the preliminary assessment of control risk. The evaluation of deviations may result in the auditor concluding that the assessed level of control risk needs to be revised. In such cases, the auditor would modify the nature, timing and extent of planned substantive procedures.\n\nBefore the conclusion of the audit, based on the results of substantive procedures and other audit evidence obtained by the auditor, the auditor should consider whether the assessment of control risk is confirmed. In case of deviations from the prescribed accounting and internal control systems, the auditor would make specific inquiries to consider their implications. Where, on the basis of such inquiries, the auditor concludes that the deviations are such that the preliminary assessment of control risk is not supported, he would amend the same unless the audit evidence obtained from other tests of control supports that assessment. Where the auditor concludes that the assessed level of control risk needs to be revised, he would modify the nature, timing and extent of his planned substantive procedures.\n\nIt has been suggested that actual operation of the internal control should be tested by the application of procedural tests and examination in depth. Procedural tests simply mean testing of the compliance with the procedures laid down by the management in respect of initiation, authorisation, recording and documentation of transaction at each stage through which it flows.","ours":{"difficulty":"medium"},"pg":{"q":"6","a":"16-17"},"tags":["aud.risk.testing","aud.risk.sa330"]},{"id":"o-p6-rtp-nov2019-q9b","section":"II","no":9,"marks":null,"type":"DESC","stem":"The extent and the nature of the audit programme is substantially influenced by the internal control system in operation. Analyse and explain.","label":"Q9(b)","part":"(b)","ord":35,"ans":"**The auditor can formulate his entire audit programme only after he has had** a satisfactory understanding of the internal control systems and their actual operation. If he does not care to study this aspect, it is very likely that his audit programme may become unwieldy and unnecessarily heavy and the object of the audit may be altogether lost in the mass of entries and vouchers. It is also important for him to know whether the system is actually in operation. Often, after installation of a system, no proper follow up is there by the management to ensure compliance. The auditor, in such circumstances, may be led to believe that a system is in operation which in reality may not be altogether in operation or may at best operate only partially. This state of affairs is probably the worst that an auditor may come across and he would be in the midst of confusion, if he does not take care.\n\nIt would be better if the auditor can undertake the review of the internal control system of client. This will give him enough time to assimilate the controls and implications and will enable him to be more objective in the framing of the audit programme. He will also be in a position to bring to the notice of the management the weaknesses of the system and to suggest measures for improvement. At a further interim date or in the course of the audit, he may ascertain how far the weaknesses have been removed.\n\nFrom the foregoing, it can be concluded that the extent and the nature of the audit programme is substantially influenced by the internal control system in operation. In deciding upon a plan of test checking, the existence and operation of internal control system is of great significance.\n\nA proper understanding of the internal control system in its content and working also enables an auditor to decide upon the appropriate audit procedure to be applied in different areas to be covered in the audit programme.\n\nIn a situation where the internal controls are considered weak in some areas, the auditor might choose an auditing procedure or test that otherwise might not be required; he might extend certain tests to cover a large number of transactions or other items than he otherwise would examine and at times he may perform additional tests to bring him the necessary satisfaction.","ours":{"difficulty":"medium"},"pg":{"q":"6","a":"17-18"},"tags":["aud.risk.ic","aud.plan.program"]},{"id":"o-p6-rtp-nov2019-q10a","section":"II","no":10,"marks":null,"type":"DESC","stem":"The SAs do not ordinarily refer to inherent risk and control risk separately, but rather to a combined assessment of the “risks of material misstatement”. Explain.","label":"Q10(a)","part":"(a)","ord":36,"ans":"The SAs do not ordinarily refer to inherent risk and control risk separately, but rather to a combined assessment of the “risks of material misstatement”. However, the auditor may make separate or combined assessments of inherent and control risk depending on preferred audit techniques or methodologies and practical considerations. The assessment of the risks of material misstatement may be expressed in quantitative terms, such as in percentages, or in non-quantitative terms. In any case, the need for the auditor to make appropriate risk assessments is more important than the different approaches by which they may be made.\n\nIt can be concluded from the above that-\n\n**Risk of Material Misstatement= Inherent Risk x Control Risk**","ours":{"difficulty":"easy"},"pg":{"q":"6","a":"18"},"tags":["aud.risk.model"]},{"id":"o-p6-rtp-nov2019-q10b","section":"II","no":10,"marks":null,"type":"DESC","stem":"The auditor of FAST CARS Ltd obtains an understanding of the control environment. As part of obtaining this understanding, the auditor evaluates whether management has created and maintained a culture of honesty and ethical behaviour and the strengths in the control environment elements collectively provide an appropriate foundation for the other components of internal control.\n\nAdvise what is included in control environment. Also explain the elements of control environment.","label":"Q10(b)","part":"(b)","ord":37,"ans":"**Control Environment – Component of Internal Control:** The auditor shall obtain an understanding of the control environment. As part of obtaining this understanding, the auditor shall evaluate whether:\n\n(i) Management has created and maintained a culture of honesty and ethical behavior; and\n\n(ii) The strengths in the control environment elements collectively provide an appropriate foundation for the other components of internal control.\n\n**What is included in Control Environment?**\n\nThe control environment includes:\n\n(i) the governance and management functions and\n\n(ii) the attitudes, awareness, and actions of those charged with governance and management.\n\n(iii) The control environment sets the tone of an organization, influencing the control consciousness of its people.\n\n**Elements of the Control Environment**: Elements of the control environment that may be relevant when obtaining an understanding of the control environment include the following:\n\n(a) **Communication and enforcement of integrity and ethical values** – These are essential elements that influence the effectiveness of the design, administration and monitoring of controls.\n\n(b) **Commitment to competence** – Matters such as management’s consideration of the competence levels for particular jobs and how those levels translate into requisite skills and knowledge.\n\n(c) **Participation by those charged with governance –** Attributes of those charged with governance such as:\n\n- Their independence from management.\n- Their experience and stature.\n- The extent of their involvement and the information they receive, and the scrutiny of activities.\n- The appropriateness of their actions, including the degree to which difficult questions are raised and pursued with management, and their interaction with internal and external auditors.\n\n(d) **Management’s philosophy and operating style – Characteristics such as management’s:**\n\n- Approach to taking and managing business risks.\n- Attitudes and actions toward financial reporting.\n- Attitudes toward information processing and accounting functions and personnel.\n\n(e) **Organisational structure** – The framework within which an entity’s activities for achieving its objectives are planned, executed, controlled, and reviewed.\n\n(f) **Assignment of authority and responsibility** - Matters such as how authority and responsibility for operating activities are assigned and how reporting relationships and authorisation hierarchies are established.\n\n(g) **Human resource policies and practices** – Policies and practices that relate to, for example, recruitment, orientation, training, evaluation, counselling, promotion, compensation, and remedial actions.","ours":{"difficulty":"medium"},"pg":{"q":"6","a":"18-19"},"tags":["aud.risk.ic","aud.risk.sa315"]},{"id":"o-p6-rtp-nov2019-q11","section":"II","no":11,"marks":null,"type":"DESC","stem":"The scope of auditor’s inquiry under **clause (x)** of paragraph 3 of Companies (Auditor’s Report) Order, 2016 is restricted to frauds ‘noticed or reported’ during the year. Explain.","label":"Q11","ord":38,"ans":"**Reporting under Companies (Auditor’s Report) Order, 2016 [CARO, 2016]:** The auditor is also required to report under **clause (x)** of paragraph 3 of Companies (Auditor’s Report) Order, 2016, whether any fraud by the company or any fraud on the Company by its officers or employees has been noticed or reported during the year. If yes, the nature and the amount involved is to be indicated.\n\nThe scope of auditor’s inquiry under **clause (x)** of paragraph 3 of Companies (Auditor’s Report) Order, 2016 is restricted to frauds ‘noticed or reported’ during the year. It may be noted that this clause of the Order, by requiring the auditor to report whether any fraud by the company or on the company by its Officer or employees has been noticed or reported, does not relieve the auditor from his responsibility to consider fraud and error in an audit of financial statements. In other words, irrespective of the auditor’s comments under this clause, the auditor is also required to comply with the requirements of SA 240, “The Auditor’s Responsibility Relating to Fraud in an Audit of Financial Statements”.\n\n**Audit Procedures and Reporting under CARO:**\n\n(1) While planning the audit, the auditor should discuss with other members of the audit team, the susceptibility of the company to material misstatements in the financial statements resulting from fraud. While planning, the auditor should also make inquiries of management to determine whether management is aware of any known fraud or suspected fraud that the company is investigating.\n\n(2) The auditor should examine the reports of the internal auditor with a view to ascertain whether any fraud has been reported or noticed by the management. The auditor should examine the minutes of the audit committee, if available, to ascertain whether any instance of fraud pertaining to the company has been reported and actions taken thereon.\n\nThe auditor should enquire from the management about any frauds on the company that it has noticed or that have been reported to it. The auditor should also discuss the matter with other employees including officers of the company. The auditor should also examine the minute book of the board meeting of the company in this regard.\n\n(3) The auditor should obtain written representations from management that:\n\n(i) it acknowledges its responsibility for the implementation and operation of accounting and internal control systems that are designed to prevent and detect fraud and error;\n\n(ii) it believes the effects of those uncorrected misstatements in financial statements, aggregated by the auditor during the audit are immaterial, both individually and in the aggregate, to the financial statements taken as a whole. A summary of such items should be included in or attached to the written representation;\n\n(iii) it has\n\n(a) disclosed to the auditor all significant facts relating to any frauds or suspected frauds known to management that may have affected the entity; and\n\n(b) disclosed to the auditor the results of its assessment of the risk that the financial statements may be materially misstated as a result of fraud.\n\n(4) Because management is responsible for adjusting the financial statements to correct material misstatements, it is important that the auditor obtains written representation from management that any uncorrected misstatements resulting from fraud are, in management's opinion, immaterial, both individually and in the aggregate. Such representations are not a substitute for obtaining sufficient appropriate audit evidence. In some circumstances, management may not believe that certain of the uncorrected financial statement misstatements aggregated by the auditor during the audit are misstatements. For that reason, management may want to add to their written representation words such as, \"We do not agree that items constitute misstatements because [description of reasons].\"\n\nThe auditor should consider if any fraud has been reported by them during the year under section 143(12) of the Act and if so whether that same would be reported under this Clause. It may be mentioned here that section 143(12) of the Act requires the auditor has reasons to believe that a fraud is being committed or has been committed by an employee or officer. In such a case the auditor needs to report to the Central Government or the Audit Committee. However, this Clause will include only the reported frauds and not suspected fraud.\n\n(5) Where the auditor notices that any fraud by the company or on the company by its officers or employees has been noticed by or reported during the year, the auditor should, apart from reporting the existence of fraud, also required to report, the nature of fraud and amount involved. For reporting under this clause, the auditor may consider the following:\n\n(i) This clause requires all frauds noticed or reported during the year shall be reported indicating the nature and amount involved. As specified the fraud by the company or on the company by its officers or employees are only covered.\n\n(ii) Of the frauds covered under section 143(12) of the Act, only noticed frauds shall be included here and not the suspected frauds.\n\n(iii) While reporting under this clause with regard to the nature and the amount involved of the frauds noticed or reported, the auditor may also consider the principles of materiality outlined in Standards on Auditing.","ours":{"difficulty":"medium"},"pg":{"q":"7","a":"19-21"},"oos":true,"note":"Out of syllabus (old scheme, ours): the item is reporting on frauds under clause (x) of paragraph 3 of CARO 2016, which CARO 2020 has replaced (its fraud clause is (xi), with different wording), and ICAI's answer builds on SA 240, old Paper 6's Chapter 5 (Fraud and Responsibilities of the Auditor in this Regard), which the new-scheme Paper 5 syllabus does not name; the January 2027 Study Material teaches CARO 2020 only. Tagged with the nearest sub-topic, CARO 2020, where today's fraud clause sits. Kept as printed: \"the auditor should, apart from reporting the existence of fraud, also required to report\", \"section 143(12) of the Act requires the auditor has reasons to believe\" and \"noticed by or reported\".","tags":["aud.report.caro"]},{"id":"o-p6-rtp-nov2019-q12","section":"II","no":12,"marks":null,"type":"DESC","stem":"Detection of manipulation of accounts with a view to presenting a false state of affairs is a task requiring great tact and intelligence. Explain stating clearly how this type of fraud is generally committed.","label":"Q12","ord":39,"ans":"**Manipulation of Accounts:** Detection of manipulation of accounts with a view to presenting a false state of affairs is a task requiring great tact and intelligence because generally management personnel in higher management cadre are associated with this type of fraud and this is perpetrated in methodical way. This type of fraud is generally committed:\n\n(a) to avoid incidence of income-tax or other taxes;\n\n(b) for declaring a dividend when there are insufficient profits;\n\n(c) to withhold declaration of dividend even when there is adequate profit (this is often done to manipulate the value of shares in stock market to make it possible for selected persons to acquire shares at a lower cost); and\n\n(d) for receiving higher remuneration where managerial remuneration is payable by reference to profits.","ours":{"difficulty":"easy"},"pg":{"q":"7","a":"21"},"oos":true,"note":"Out of syllabus (old scheme, ours): the manipulation of accounts by management and the purposes behind it belonged to old Paper 6's Chapter 5, Fraud and Responsibilities of the Auditor in this Regard (SA 240); the new-scheme Paper 5 syllabus does not name SA 240 and the January 2027 Study Material mentions it only in passing, so the item carries only its nearest chapter, Risk Assessment and Internal Control (as o-p6-rtp-nov2022 q11 and q12).","tags":["aud.risk"]},{"id":"o-p6-rtp-nov2019-q13","section":"II","no":13,"marks":null,"type":"DESC","stem":"Give some of the points that an auditor should consider to obtain an understanding of the company’s automated environment:","label":"Q13","ord":40,"ans":"Given below are some of the points that an auditor should consider to obtain an understanding of the company’s automated environment:\n\n- Information systems being used (one or more application systems and what they are).\n- Their purpose (financial and non-financial).\n- Location of IT systems - local vs global.\n- Architecture (desktop based, client-server, web application, cloud based).\n- Version (functions and risks could vary in different versions of same application).\n- Interfaces within systems (in case multiple systems exist).\n- In-house vs Packaged.\n- Outsourced activities (IT maintenance and support).\n- Key persons (CIO, CISO, Administrators).","ours":{"difficulty":"easy"},"pg":{"q":"7","a":"22"},"tags":["aud.risk.it"]},{"id":"o-p6-rtp-nov2019-q14","section":"II","no":14,"marks":null,"type":"DESC","stem":"Having obtained an understanding of the IT systems and the automated environment of a company, the auditor should understand the risks that arise from the use of IT systems. Explain those risks.","label":"Q14","ord":41,"ans":"Having obtained an understanding of the IT systems and the automated environment of a company, the auditor should now understand the risks that arise from the use of IT systems.\n\nGiven below are some such risks that should be considered:\n\n- Inaccurate processing of data, processing inaccurate data, or both.\n- Unauthorized access to data.\n- Direct data changes (backend changes).\n- Excessive access / Privileged access (super users).\n- Lack of adequate segregation of duties.\n- Unauthorized changes to systems or programs.\n- Failure to make necessary changes to systems or programs.\n- Loss of data.","ours":{"difficulty":"easy"},"pg":{"q":"7","a":"22"},"tags":["aud.risk.it"]},{"id":"o-p6-rtp-nov2019-q15","section":"II","no":15,"marks":null,"type":"DESC","stem":"There is a growing realisation that the traditional approach to audit is economically wasteful because all efforts are directed to check all transactions without exception. Explain","label":"Q15","ord":42,"ans":"No conscious effort in human society is divested of economic considerations and auditing is no exception. There is a growing realisation that the traditional approach to audit is economically wasteful because all efforts are directed to check all transactions without exception. This invariably leads to more emphasis on routine checking, which often is not necessary in view of the time and the cost involved. With the shift in favour of formal internal controls in the management of affairs of organisations, the possibilities of routine errors and frauds have greatly diminished and auditors often find extensive routine checking as nothing more than a ritual because it seldom reveals anything material. Now the approach to audit and the extent of checking are undergoing a progressive change in favour of more attention towards the questions of principles and controls with a curtailment of non-consequential routine checking. By routine checking we traditionally think of extensive checking and vouching of all entries.","ours":{"difficulty":"easy"},"pg":{"q":"7","a":"22-23"},"tags":["aud.evid.sa530"]},{"id":"o-p6-rtp-nov2019-q16","section":"II","no":16,"marks":null,"type":"DESC","stem":"The extent of the checking to be undertaken is primarily a matter of judgment of the auditor. It is in the interest of the auditor that if he decides to form his opinion on the basis of a part checking, he should adopt standards and techniques which are widely followed Explain","label":"Q16","ord":43,"ans":"The extent of the checking to be undertaken is primarily a matter of judgment of the auditor, there is nothing statutorily stated anywhere which specifies what work is to be done, how it is to be done and to what extent. It is also not obligatory that the auditor must adopt the sampling technique. What he is to do is to express his opinion and become bound by that.\n\nTo ensure good and reasonable standard of work, he should adopt standards and techniques that can lead him to an informed professional opinion. On a consideration of this fact, it can be said that it is in the interest of the auditor that if he decides to form his opinion on the basis of a part checking, he should adopt standards and techniques which are widely followed and which have a recognised basis. Since statistical theory of sampling is based on a scientific law, it can be relied upon to a greater extent than any arbitrary technique which lacks in basis and acceptability.","ours":{"difficulty":"easy"},"pg":{"q":"7","a":"23"},"tags":["aud.evid.sa530"]},{"id":"o-p6-rtp-nov2019-q17","section":"II","no":17,"marks":null,"type":"DESC","stem":"Routine checks cannot be depended upon to disclose all the mistakes or manipulation that may exist in accounts, certain other procedures also have to be applied like trend and ratio analysis. Analyse and Explain stating clearly the meaning of analytical procedures.","label":"Q17","ord":44,"ans":"Since routine checks cannot be depended upon to disclose all the mistakes or manipulation that may exist in accounts, certain other procedures also have to be applied like trend and ratio analysis in addition to reasonable tests. These collectively are known as overall tests. With the passage of tests, analytical procedures have acquired lot of significance as substantive audit procedure. SA-520 on Analytical Procedures discusses the application of analytical procedures during an audit.\n\n**Meaning of Analytical Procedures.** As per the Standard on Auditing (SA) 520 “Analytical Procedures”, the term “analytical procedures” means evaluations of financial information through analysis of plausible relationships among both financial and non-financial data. Analytical procedures also encompass such investigation as is necessary of identified fluctuations or relationships that are inconsistent with other relevant information or that differ from expected values by a significant amount.","ours":{"difficulty":"easy"},"pg":{"q":"7","a":"23"},"tags":["aud.evid.sa520"]},{"id":"o-p6-rtp-nov2019-q18","section":"II","no":18,"marks":null,"type":"DESC","stem":"Give examples of Analytical Procedures having consideration of comparisons of the entity’s financial information","label":"Q18","ord":45,"ans":"**Examples of Analytical Procedures having consideration of comparisons of the entity’s financial information with are:**\n\n- Comparable information for prior periods.\n- Anticipated results of the entity, such as budgets or forecasts, or expectations of the auditor, such as an estimation of depreciation.\n- Similar industry information, such as a comparison of the entity’s ratio of sales to accounts receivable with industry averages or with other entities of comparable size in the same industry","ours":{"difficulty":"easy"},"pg":{"q":"7","a":"23"},"tags":["aud.evid.sa520"]},{"id":"o-p6-rtp-nov2019-q19","section":"II","no":19,"marks":null,"type":"DESC","stem":"The auditor A of ABC & Co.- firm of auditors is conducting the audit of XYZ Ltd and while performing testing of additions wanted to verify that all PPE (Property Plant and Equipment) purchase invoices are in the name of the entity he is auditing. For all additions to land, building in particular, the auditor desires to have concrete evidence about ownership. The auditor is worried about whether the entity has valid legal ownership rights over the PPE claimed to be held by the entity and recorded in the financial statements. Advise the auditor.","label":"Q19","ord":46,"ans":"In addition to the procedures undertaken for verifying completeness of additions to PPE during the period under audit, the auditor while performing testing of additions should also verify that all PPE purchase invoices are in the name of the entity that entitles legal title of ownership to the respective entity. For all additions to land, building in particular, the auditor should obtain copies of conveyance deed/ sale deed to establish whether the entity is mentioned to be the legal and valid owner.\n\nThe auditor should insist and verify the original title deeds for all immoveable properties held as at the balance sheet date. In case the entity has given such immoveable property as security for any borrowings and the original title deeds are not available with the entity, the auditor should request the entity’s management for obtaining a confirmation from the respective lenders that they are holding the original title deeds of immoveable property as security. In addition, the auditor should also verify the register of charges, available with the entity to assess the PPE that has been given as security to any third parties","ours":{"approach":"Ownership (rights and obligations) is proved by documents of title: think of where the original deeds are and how to confirm them when a lender holds them.","difficulty":"easy"},"pg":{"q":"7","a":"23-24"},"tags":["aud.items.ppe"]},{"id":"o-p6-rtp-nov2019-q20","section":"II","no":20,"marks":null,"type":"DESC","stem":"Explain with examples the audit procedure to establish the existence of intangible fixed assets as at the period- end.","label":"Q20","ord":47,"ans":"**Since an Intangible Asset is an identifiable non-monetary asset,** without physical substance, for establishing the existence of such assets, the auditor should verify whether such intangible asset is in active use in the production or supply of goods or services, for rental to others, or for administrative purposes.\n\nExample- for verifying the existence of software, the auditor should verify whether such software is in active use by the entity and for the purpose, the auditor should verify the sale of related services/ goods during the period under audit, in which such software has been used.\n\nExample- For verifying the existence of design/ drawings, the auditor should verify the production data to establish if such products for which the design/ drawings were purchased, are being produced and sold by the entity.\n\nIn case any intangible asset is not in active use, deletion should have been recorded in the books of account post approvals by the entity’s management and amortization charge should have ceased to be charged beyond the date of deletion","ours":{"difficulty":"easy"},"pg":{"q":"7","a":"24"},"note":"ICAI's answer runs on, on the same line, into the next chapter heading (\"... beyond the date of deletion Chapter 10 - The Company Audit\"); the heading is not part of the answer and is not transcribed, and the answer ends without a full stop, as printed.","tags":["aud.items.ppe"]},{"id":"o-p6-rtp-nov2019-q21","section":"II","no":21,"marks":null,"type":"DESC","stem":"The practice of appointing Chartered Accountants as joint auditors is quite widespread in big companies and corporations. Explain stating the advantages of the joint audit.","label":"Q21","ord":48,"ans":"**Joint Audit:** The practice of appointing Chartered Accountants as joint auditors is quite widespread in big companies and corporations. Joint audit basically implies pooling together the resources and expertise of more than one firm of auditors to render an expert job in a given time period which may be difficult to accomplish acting individually. It essentially involves sharing of the total work. This is by itself a great advantage.\n\nIn specific terms the **advantages** that flow may be the following:\n\n(i) Sharing of expertise.\n\n(ii) Advantage of mutual consultation.\n\n(iii) Lower workload.\n\n(iv) Better quality of performance.\n\n(v) Improved service to the client.\n\n(vi) Displacement of the auditor of the company taken over in a takeover often obviated.\n\n(vii) In respect of multi-national companies, the work can be spread using the expertise of the local firms which are in a better position to deal with detailed work and the local laws and regulations.\n\n(viii) Lower staff development costs.\n\n(ix) Lower costs to carry out the work.\n\n(x) A sense of healthy competition towards a better performance","ours":{"difficulty":"easy"},"pg":{"q":"8","a":"24-25"},"tags":["aud.report.branch"]},{"id":"o-p6-rtp-nov2019-q22","section":"II","no":22,"marks":null,"type":"DESC","stem":"According to Companies Act, 2013, the person appointed as an auditor of the company shall sign the auditor's report in accordance with the relevant provisions of the Act. Explain clearly the relevant provisions relating to signing of report.","label":"Q22","ord":49,"ans":"**Duty to Sign the Audit Report:** As per **section 145** of the Companies Act, 2013, the person appointed as an auditor of the company shall sign the auditor's report or sign or certify any other document of the company, in accordance with the provisions of **section 141(2)**.\n\n**Section 141(2)** of the Companies Act, 2013 states that where a firm including a limited liability partnership is appointed as an auditor of a company, only the partners who are chartered accountants shall be authorised to act and sign on behalf of the firm.\n\nThe qualifications, observations or comments on financial transactions or matters, which have any adverse effect on the functioning of the company mentioned in the auditor's report shall be read before the company in general meeting.","ours":{"difficulty":"easy"},"pg":{"q":"8","a":"25"},"oos":true,"note":"Out of syllabus (old scheme, ours): the auditor's duty to sign the report under section 145 of the Companies Act, 2013 (with section 141(2) and the reading of adverse remarks at the general meeting) belonged to old Paper 6's Chapter 10, The Company Audit (rights and duties of the auditor); the new-scheme Paper 5 syllabus and the January 2027 Study Material do not teach these sections (SA 700 covers only the signature on the report), so the item carries the nearest sub-topic, SA 700.","tags":["aud.report.sa700"]},{"id":"o-p6-rtp-nov2019-q23","section":"II","no":23,"marks":null,"type":"DESC","stem":"The auditor shall make a report to the members of the company on the accounts examined by him. Explain with reference to relevant provisions of the Companies Act, 2013.","label":"Q23","ord":50,"ans":"**Right to report to the members of the company on the accounts examined by him –** The auditor shall make a report to the members of the company on the accounts examined by him and on every financial statements which are required by or under this Act to be laid before the company in general meeting and the report shall after taking into account the provisions of this Act, the accounting and auditing standards and matters which are required to be included in the audit report under the provisions of this Act or any rules made there under or under any order made under this section and to the best of his information and knowledge, the said accounts, financial statements give a true and fair view of the state of the company’ s affairs as at the end of its financial year and profit or loss and cash flow for the year and such other matters as may be prescribed.","ours":{"difficulty":"easy"},"pg":{"q":"8","a":"25"},"note":"Kept as printed: \"the company’ s affairs\" (a space inside the apostrophe on the page) and \"made there under\".","tags":["aud.report.companies"]},{"id":"o-p6-rtp-nov2019-q24","section":"II","no":24,"marks":null,"type":"DESC","stem":"Communicating Key Audit Matter is not a substitute for disclosure in the Financial Statements rather Communicating key audit matters in the auditor’s report is in the context of the Auditor having formed an opinion on the financial statements as a whole. Analyse.","label":"Q24","ord":51,"ans":"**Communicating key audit matters in the auditor’s report is not:**\n\n(i) A substitute for disclosures in the financial statements that the applicable Financial reporting framework requires management to make, or that are otherwise necessary to achieve fair presentation;\n\n(ii) A substitute for the auditor expressing a modified opinion when required by the circumstances of a specific audit engagement in accordance with SA 705 (Revised);\n\n(iii) A substitute for reporting in accordance with SA 570 when a material uncertainty exists relating to events or conditions that may cast significant doubt on an entity’s ability to continue as a going concern; or\n\n(iv) A separate opinion on individual matters","ours":{"difficulty":"easy"},"pg":{"q":"8","a":"25"},"tags":["aud.report.sa701"]},{"id":"o-p6-rtp-nov2019-q25","section":"II","no":25,"marks":null,"type":"DESC","stem":"The auditor’s report shall include a section, directly following the Opinion section, with the heading “Basis for Opinion”. Explain what is included in this “Basis for Opinion” section.","label":"Q25","ord":52,"ans":"**Basis for Opinion:** The auditor’s report shall include a section, directly following the Opinion section, with the heading **“Basis for Opinion”**, that:\n\n(a) States that the audit was conducted in accordance with Standards on Auditing;\n\n(b) Refers to the section of the auditor’s report that describes the auditor’s responsibilities under the SAs;\n\n(c) Includes a statement that the auditor is independent of the entity in accordance with the relevant ethical requirements relating to the audit and has fulfilled the auditor’s other ethical responsibilities in accordance with these requirements.\n\n(d) States whether the auditor believes that the audit evidence the auditor has obtained is sufficient and appropriate to provide a basis for the auditor’s opinion.","ours":{"difficulty":"easy"},"pg":{"q":"8","a":"26"},"tags":["aud.report.sa700"]},{"id":"o-p6-rtp-nov2019-q26a","section":"II","no":26,"marks":null,"type":"DESC","stem":"Advances generally constitute the major part of the assets of the bank. There are large number of borrowers to whom variety of advances are granted. The audit of advances requires the major attention from the auditors. In carrying out audit of advances, the auditor is primarily concerned with obtaining evidence about, among other points, the amounts included in balance sheet in respect of advances are outstanding at the date of the balance sheet. Explain","label":"Q26(a)","part":"(a)","ord":53,"ans":"**Audit of Advances:** Advances generally constitute the major part of the assets of the bank. There are large number of borrowers to whom variety of advances are granted. The audit of advances requires the major attention from the auditors.\n\nIn carrying out audit of advances, the auditor is primarily concerned with obtaining evidence about the following:\n\n(a) Amounts included in balance sheet in respect of advances are outstanding at the date of the balance sheet.\n\n(b) Advances represent amount due to the bank.\n\n(c) Amounts due to the bank are appropriately supported by Loan documents and other documents as applicable to the nature of advances.\n\n(d) There are no unrecorded advances.\n\n(e) The stated basis of valuation of advances is appropriate and properly applied, and that the recoverability of advances is recognised in their valuation.\n\n(f) The advances are disclosed, classified and described in accordance with recognised accounting policies and practices and relevant statutory and regulatory requirements.\n\n(g) Appropriate provisions towards advances have been made as per the RBI norms, Accounting Standards and generally accepted accounting practices.","ours":{"difficulty":"easy"},"pg":{"q":"8","a":"26"},"tags":["aud.bank.advances"]},{"id":"o-p6-rtp-nov2019-q26b","section":"II","no":26,"marks":null,"type":"DESC","stem":"The auditor can obtain sufficient appropriate audit evidence about advances by study and evaluation of internal controls relating to advances. Explain in the context of Audit of Banks.","label":"Q26(b)","part":"(b)","ord":54,"ans":"The auditor can obtain sufficient appropriate audit evidence about advances by study and evaluation of internal controls relating to advances, and by:\n\n- examining the validity of the recorded amounts;\n- examining loan documentation;\n- reviewing the operation of the accounts;\n- examining the existence, enforceability and valuation of the security;\n- checking compliance with RBI norms including appropriate classification and provisioning; and\n- carrying out appropriate analytical procedures.\n\nIn carrying out his substantive procedures, the auditor should examine all large advances while other advances may be examined on a sampling basis. The accounts identified to be problem accounts however need to be examined in detail unless the amount involved is insignificant.\n\nAdvances which are sanctioned during the year or which are adversely commented by RBI inspection team, concurrent auditors, bank’s internal inspection, etc. should generally be included in the auditor’s review.","ours":{"difficulty":"easy"},"pg":{"q":"8","a":"26-27"},"tags":["aud.bank.advances","aud.bank.approach"]},{"id":"o-p6-rtp-nov2019-q27a","section":"II","no":27,"marks":null,"type":"DESC","stem":"Audit of government expenditure is one of the major components of government audit conducted by the office of C&AG. The basic standards set for audit of expenditure are to ensure that there is provision of funds authorised by competent authority fixing the limits within which expenditure can be incurred. Explain those standards.","label":"Q27(a)","part":"(a)","ord":55,"ans":"**Government Expenditure Audit:** Audit of government expenditure is one of the major components of government audit conducted by the office of C&AG. The basic standards set for audit of expenditure are to ensure that there is provision of funds authorised by competent authority fixing the limits within which expenditure can be incurred. **Briefly, these standards are explained below:**\n\n(i) **Audit against Rules & Orders:** The auditor has to see that the expenditure incurred conforms to the relevant provisions of the statutory enactment and is in accordance with the financial rules and regulations framed by the competent authority.\n\n(ii) **Audit of Sanctions:** The auditor has to ensure that each item of expenditure is covered by a sanction, either general or special, accorded by the competent authority, authorising such expenditure.\n\n(iii) **Audit against Provision of Funds:** It contemplates that there is a provision of funds out of which expenditure can be incurred and the amount of such expenditure does not exceed the appropriations made.\n\n(iv) **Propriety Audit:** It is required to be seen that the expenditure is incurred with due regard to broad and general principles of financial propriety. The auditor aims to bring out cases of improper, avoidable, or in fructuous expenditure even though the expenditure has been incurred in conformity with the existing rules and regulations. Audit aims to secure a reasonably high standard of public financial morality by looking into the wisdom, faithfulness and economy of transactions.\n\n(v) **Performance Audit:** This involves that the various programmes, schemes and projects where large financial expenditure has been incurred are being run economically and are yielding results expected of them. Efficiency-cum-performance audit, wherever used, is an objective examination of the financial and operational performance of an organisation, programme, authority or function and is oriented towards identifying opportunities for greater economy, and effectiveness.","ours":{"difficulty":"easy"},"pg":{"q":"8","a":"27"},"tags":["aud.entities.govt"]},{"id":"o-p6-rtp-nov2019-q27b","section":"II","no":27,"marks":null,"type":"DESC","stem":"Explain in detail the duties of Comptroller and Auditor General of India.","label":"Q27(b)","part":"(b)","ord":56,"ans":"**Duties of C&AG: The Comptroller & Auditor General’s (Duties, Powers and Conditions of Service) Act, 1971 lays down duties of the C&AG as under-**\n\n(i) **Compile and submit Accounts of Union and States -** The C&AG shall be responsible for compiling the accounts of the Union and of each State from the initial and subsidiary accounts rendered to the audit and accounts offices under his control by treasuries, offices or departments responsible for the keeping of such account.\n\n(ii) **General Provisions Relating to Audit - It shall be the duty of the C&AG –**\n\n(a) to audit and report on all expenditure from the Consolidated Fund of India and of each State and of each Union Territory having a Legislative Assembly and to ascertain whether the moneys shown in the accounts as having been disbursed were legally available for and applicable to the service or purpose to which they have been applied or charged and whether the expenditure conforms to the authority which governs it;\n\n(b) to audit and report all transactions of the Union and of the States relating to Contingency Funds and Public Accounts;\n\n(c) to audit and report on all trading, manufacturing profit and loss accounts and balance-sheets and other subsidiary accounts kept in any department of the Union or of a State.\n\n(iii) **Audit of Receipts and Expenditure -** Where any body or authority is substantially financed by grants or loans from the Consolidated Fund of India or of any State or of any Union Territory having a Legislative Assembly, the Comptroller and Auditor General shall, subject to the provisions of any law for the time being in force applicable to the body or authority, as the case may be, audit all receipts and expenditure of that body or authority and to report on the receipts and expenditure audited by him.\n\n(iv) **Audit of Grants or Loans -** Where any grant or loan is given for any specific purpose from the Consolidated Fund of India or of any State or of any Union Territory having a Legislative Assembly to any authority or body, not being a foreign State or international organisation, the Comptroller and Auditor General shall scrutinise the procedures by which the sanctioning authority satisfies itself as to the fulfillment of the conditions subject to which such grants or loans were given and shall for this purpose have right of access, after giving reasonable previous notice, to the books and accounts of that authority or body.\n\n(v) **Audit of Receipts of Union or States** - It shall be the duty of the Comptroller and Auditor General to audit all receipts which are payable into the Consolidated Fund of India and of each State and of each Union Territory having a Legislative Assembly and to satisfy himself that the rules and procedures in that behalf are designed to secure an effective check on the assessment, collection and proper allocation of revenue and are being duly observed and to make this purpose such examination of the accounts as he thinks fit and report thereon.\n\n(vi) **Audit of Accounts of Stores and Inventory -** The Comptroller and Auditor General shall have authority to audit and report on the accounts of stores and inventory kept in any office or department of the Union or of a State.\n\n(vii) **Audit of Government Companies and Corporations -** The duties and powers of the Comptroller and Auditor General in relation to the audit of the accounts of government companies shall be performed and exercised by him in accordance with the provisions of the Companies Act, 2013. The comptroller and Auditor - General of India shall appoint the auditor under sub-section (5) or sub-section (7) of section 139 (i.e. appointment of First Auditor or Subsequent Auditor) and direct such auditor the manner in which the accounts of the Government company are required to be audited and thereupon the auditor so appointed shall submit a copy of the audit report to the Comptroller and Auditor-General of India which, among other things, include the directions, if any, issued by the Comptroller and Auditor-General of India, the action taken thereon and its impact on the accounts and financial statement of the company.","ours":{"difficulty":"medium"},"pg":{"q":"8","a":"28-29"},"tags":["aud.entities.govt"]},{"id":"o-p6-rtp-nov2019-q28","section":"II","no":28,"marks":null,"type":"DESC","stem":"What are the special steps involved in conducting the audit of an Educational Institution?","label":"Q28","ord":57,"ans":"**The Special Steps Involved in the Audit of an Educational Institution are the following:**\n\n(i) Examine the Trust Deed, or Regulations in the case of school or college and note all the provisions affecting accounts. In the case of a university, refer to the Act of Legislature and the Regulations framed thereunder.\n\n(ii) Read through the minutes of the meetings of the Managing Committee or Governing Body, noting resolutions affecting accounts to see that these have been duly complied with, specially the decisions as regards the operation of bank accounts and sanctioning of expenditure.\n\n(iii) Check names entered in the Students’ Fee Register for each month or term, with the respective class registers, showing names of students on rolls and test amount of fees charged; and verify that there operates a system of internal check which ensures that demands against the students are properly raised.\n\n(iv) Check fees received by comparing counterfoils of receipts granted with entries in the cash book and tracing the collections in the Fee Register to confirm that the revenue from this source has been duly accounted for.\n\n(v) Total up the various columns of the Fees Register for each month or term to ascertain that fees paid in advance have been carried forward and the arrears that are irrecoverable have been written off under the sanction of an appropriate authority.\n\n(vi) Check admission fees with admission slips signed by the head of the institution and confirm that the amount had been credited to a Capital Fund, unless the Managing Committee has taken a decision to the contrary.\n\n(vii) See that free studentship and concessions have been granted by a person authorised to do so, having regard to the prescribed Rules.\n\n(viii) Confirm that fines for late payment or absence, etc., have either been collected or remitted under proper authority.\n\n(ix) Confirm that hostel dues were recovered before students’ accounts were closed and their deposits of caution money refunded.\n\n(x) Verify rental income from landed property with the rent rolls, etc.\n\n(xi) Vouch income from endowments and legacies, as well as interest and dividends from investment; also inspect the securities in respect of investments held.\n\n(xii) Verify any Government or local authority grant with the relevant papers of grant. If any expense has been disallowed for purposes of grant, ascertain the reasons and compliance thereof.\n\n(xiii) Report any old heavy arrears on account of fees, dormitory rents, etc, to the Managing Committee.\n\n(xiv) Confirm that caution money and other deposits paid by students on admission have been shown as liability in the balance sheet and not transferred to revenue.\n\n(xv) See that the investments representing endowment funds for prizes are kept separate and any income in excess of the prizes has been accumulated and invested along with the corpus.\n\n(xvi) Verify that the Provident Fund money of the staff has been invested in appropriate securities.\n\n(xvii) Vouch donations, if any, with the list published with the annual report. If some donations were meant for any specific purpose, see that the money was utilised for the purpose.\n\n(xviii) Vouch all capital expenditure in the usual way and verify the same with the sanction for the Committee as contained in the minute book.\n\n(xix) Vouch in the usual manner all establishment expenses and enquire into any unduly heavy expenditure under any head.\n\n(xx) See that increase in the salaries of the staff have been sanctioned and minuted by the Committee.\n\n(xxi) Ascertain that the system ordering inspection on receipt and issue of provisions, foodstuffs, clothing and other equipment is efficient and all bills are duly authorised and passed before payment.\n\n(xxii) Verify the inventories of furniture, stationery, clothing, provision and all equipment, etc. These should be checked by reference to Inventory Register and values applied to various items should be test checked.\n\n(xxiii) Confirm that the refund of taxes deducted from the income from investment (interest on securities, etc.) has been claimed and recovered since the institutions are generally exempted from the payment of income-tax.\n\n(xxiv) Verify the annual statements of accounts and while doing so see that separate statements of account have been prepared as regards Poor Boys Fund, Games Fund, Hostel and Provident Fund of Staff, etc.","ours":{"difficulty":"easy"},"pg":{"q":"8","a":"29-31"},"tags":["aud.entities.institutions"]}]);
